import dataUrl from './refueling-data.json?url';
import { setLoading } from '../core/loading';

// US air refueling tracks: the published lines tankers fly while they
// refuel, the same ones tar1090 draws as "US A2A Refueling". Used by
// world/activity.ts to say a military aircraft is on one and drawn by
// world/refueling-layer.ts. The data gives centrelines only, no heights.
//
// refueling-data.json is generated by scripts/build-refueling.py from
// tar1090's overlay and is GPL v2+ like it; regenerate, do not hand-edit.
// Fetched on first use.

export interface RefuelTrack {
  /** As published: "AR-109", "AR-7A South". */
  id: string;
  /** Centreline, [lat, lon], in the published order. */
  pts: [number, number][];
  /** [minLat, minLon, maxLat, maxLon]. */
  bbox: [number, number, number, number];
}

/** Parse the generated file. Entries that do not fit are dropped. */
export function decodeRefuelTracks(raw: unknown): RefuelTrack[] {
  const list = (raw as { tracks?: unknown } | null)?.tracks;
  if (!Array.isArray(list)) return [];
  const out: RefuelTrack[] = [];
  for (const item of list as { id?: unknown; pts?: unknown }[]) {
    if (typeof item?.id !== 'string' || !Array.isArray(item.pts)) continue;
    const pts = (item.pts as unknown[]).filter(
      (p): p is [number, number] => Array.isArray(p) && p.length === 2 && p.every((n) => typeof n === 'number'),
    );
    if (pts.length < 2) continue;
    const bbox: [number, number, number, number] = [90, 180, -90, -180];
    for (const [lat, lon] of pts) {
      if (lat < bbox[0]) bbox[0] = lat;
      if (lon < bbox[1]) bbox[1] = lon;
      if (lat > bbox[2]) bbox[2] = lat;
      if (lon > bbox[3]) bbox[3] = lon;
    }
    out.push({ id: item.id, pts, bbox });
  }
  return out;
}

export interface RefuelDrawing {
  /** Line pieces as lat0, lon0, lat1, lon1, ... */
  pieces: number[];
  /** One per track that comes near enough to name, nearest first: where its line is closest to the middle. */
  labels: { id: string; lat: number; lon: number; nm: number }[];
}

/**
 * Pure: the parts of the tracks inside `reachNm` of the scope's middle, cut
 * into pieces no longer than `maxPieceNm` so they can follow the ground.
 * Legs run to hundreds of miles, so one can cross the scope with both ends
 * outside it: a leg is only skipped when it is too far away to reach in.
 */
export function refuelDrawing(
  list: readonly RefuelTrack[],
  distanceNm: (lat: number, lon: number) => number,
  reachNm: number,
  maxPieceNm: number,
  labelNm: number,
  maxLabels: number,
): RefuelDrawing {
  const pieces: number[] = [];
  const labels: RefuelDrawing['labels'] = [];
  for (const track of list) {
    let nearest: { lat: number; lon: number; nm: number } | null = null;
    for (let i = 0; i + 1 < track.pts.length; i++) {
      const [aLat, aLon] = track.pts[i]!;
      const [bLat, bLon] = track.pts[i + 1]!;
      const legNm = Math.hypot((bLat - aLat) * 60, (bLon - aLon) * 60 * Math.cos((aLat * Math.PI) / 180));
      if (distanceNm(aLat, aLon) > reachNm + legNm) continue;
      const n = Math.max(1, Math.ceil(legNm / maxPieceNm));
      let lat0 = aLat;
      let lon0 = aLon;
      let d0 = distanceNm(lat0, lon0);
      for (let k = 1; k <= n; k++) {
        const lat1 = aLat + ((bLat - aLat) * k) / n;
        const lon1 = aLon + ((bLon - aLon) * k) / n;
        const d1 = distanceNm(lat1, lon1);
        if (d0 <= reachNm || d1 <= reachNm) {
          pieces.push(lat0, lon0, lat1, lon1);
          if (d0 <= labelNm && (!nearest || d0 < nearest.nm)) nearest = { lat: lat0, lon: lon0, nm: d0 };
        }
        lat0 = lat1;
        lon0 = lon1;
        d0 = d1;
      }
    }
    if (nearest) labels.push({ id: track.id, ...nearest });
  }
  labels.sort((a, b) => a.nm - b.nm);
  return { pieces, labels: labels.slice(0, maxLabels) };
}

let tracks: RefuelTrack[] | null = null;
let loading: Promise<void> | null = null;
const listeners = new Set<() => void>();

export function getRefuelTracks(): readonly RefuelTrack[] | null {
  return tracks;
}

export function subscribeRefuelTracks(fn: () => void): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

/** `label` names the fetch in the loading toast; the aircraft card's background load passes none. */
export function loadRefuelTracks(label?: string): void {
  if (tracks || loading) return;
  if (label) setLoading('refueling', label);
  loading = fetch(dataUrl)
    .then((res) => {
      if (!res.ok) throw new Error(`refueling tracks: HTTP ${res.status}`);
      return res.json() as Promise<unknown>;
    })
    .then((raw) => {
      tracks = decodeRefuelTracks(raw);
      for (const fn of listeners) fn();
    })
    .catch((err: unknown) => {
      console.warn('[refueling] could not load', err);
      loading = null;
    })
    .finally(() => setLoading('refueling', null));
}
